/* Monarca · complete local account, care and service flows. */
(() => {
'use strict';
const M=window.Monarca;
if(!M)return;
const {esc,icon,money,ar,top,btn,goto}=M;
const S=()=>M.state,U=M.ui;
const day=86400000;
const rules={M10:{code:'M10',title:'لمسة ترحيب',description:'خصم ١٠٪ على قيمة المنتجات',min:M.commerce.couponMin,type:'percent',value:10}};
const freeDeliveryText='رسوم التوصيل التجريبية ٤ USD للطلب، والتوصيل مجاني من ٧٥ USD قبل الخصم، ولا يحتاج قسيمة.';
const preferences={orders:true,offers:true,services:true};
function ensure(){const s=S();s.profile=s.profile||{};s.notificationPreferences={...preferences,...s.notificationPreferences};s.paymentTokens=Array.isArray(s.paymentTokens)?s.paymentTokens.filter(t=>t&&t.isDemo&&['visa','mastercard'].includes(t.network)):[];s.tickets=Array.isArray(s.tickets)?s.tickets:[];if(!Array.isArray(s.couponWallet))s.couponWallet=[{id:'M10',code:'M10',claimed:false,expires:Date.now()+30*day},{id:'PAST-EDIT',code:'EDIT10',claimed:true,expires:new Date('2026-09-30T23:59:59+03:00').getTime(),archivedDemo:true}];if(!Array.isArray(s.notificationRecords))s.notificationRecords=[{id:'welcome',category:'service',title:'أهلاً بكِ في Monarca',body:'تفاصيل صغيرة، وتجربة أقرب إليك. تعرّفي على حسابك وخياراتك.',icon:'user',route:'account',read:false,time:Date.now()-3600000},{id:'offer-m10',category:'offers',title:'هدية لاختياراتك الأولى',body:'خصم ١٠٪ بالرمز M10 للطلبات من ٤٠ USD.',icon:'tag',route:'coupons',read:false,time:Date.now()-7200000},{id:'delivery-info',category:'service',title:'إلى جميع أنحاء العراق',body:'أكملي المدينة والعنوان والنقطة الدالة لتسهيل التوصيل.',icon:'truck',route:'addresses',read:true,time:Date.now()-day}];syncOrderNotifications(s);s.security=s.security||{loginRecords:[]};if(!Array.isArray(s.security.loginRecords))s.security.loginRecords=[];return s;}
function syncOrderNotifications(s){const names={payment_pending:'بانتظار إكمال الدفع',placed:'تم تأكيد طلبك',preparing:'طلبك قيد التجهيز',shipped:'طلبك في الطريق',delivered:'وصلت اختياراتك',cancelled:'تم إلغاء الطلب',returned:'تحديث الإرجاع'};for(const o of s.orders.slice(0,30)){if(!names[o.status])continue;const id='order-status-'+o.id+'-'+o.status;if(s.notificationRecords.some(n=>n.id===id))continue;s.notificationRecords.push({id,category:'orders',title:names[o.status],body:'الطلب '+o.id+(o.sample?' · طلب توضيحي':'')+' — تابعي التفاصيل والإجراءات المتاحة من صفحة الطلب.',icon:o.status==='shipped'?'truck':o.status==='payment_pending'?'card':'box',route:'order/'+o.id,read:!!o.sample,time:Number(o.updatedAt)||Number(o.createdAt)||Date.now()});}}
function persist(){M.save();}
function date(v,withTime=false){const d=new Date(v);return isNaN(d)?'—':new Intl.DateTimeFormat(M.locale?.()||'ar-IQ',{day:'numeric',month:'short',...(withTime?{hour:'2-digit',minute:'2-digit'}:{}),timeZone:'Asia/Baghdad'}).format(d);}
function amountText(v){return M.moneyText(v);}
const digits=v=>String(v||'').replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d));
const note=(text,ico='info')=>`<div class="ac-note">${icon(ico)}<p>${text}</p></div>`;
const section=(title,body,extra='')=>`<section class="ac-section"><div class="ac-heading"><h2>${title}</h2>${extra}</div>${body}</section>`;
const menu=(i,title,sub,route,badge='')=>`<button class="ac-menu" data-go="${route}"><span class="ac-menu-icon">${icon(i)}</span><span><b>${title}</b>${sub?`<small>${sub}</small>`:''}</span>${badge?`<em>${badge}</em>`:''}${icon('arrow')}</button>`;
const head=(overline,title,text)=>`<p class="overline ac-overline">${overline}</p><h2 class="ac-title">${title}</h2>${text?`<p class="ac-lead">${text}</p>`:''}`;
const tabs=(items,selected,action)=>`<div class="ac-tabs" role="group">${items.map(([id,n])=>btn(n,action,'ac-tab'+(id===selected?' active':''),`data-value="${id}" aria-pressed="${id===selected}"`)).join('')}</div>`;
function inlineError(id,text){const node=document.getElementById(id);if(node){node.textContent=text;node.hidden=false;node.focus();}}
function couponStatus(c){return c.usedAt?'used':c.expires<Date.now()?'expired':c.claimed?'ready':'claim';}
function validateCoupon(code,subtotal){ensure();code=String(code||'').trim().toUpperCase();if(code==='FREE100')return {ok:false,automaticShipping:true,reason:freeDeliveryText};const r=rules[code],c=S().couponWallet.find(c=>c.code===code);if(!r||!c)return {ok:false,reason:'رمز القسيمة غير صالح.'};if(c.usedAt)return {ok:false,reason:'تم استخدام هذه القسيمة سابقاً.'};if(c.expires<Date.now())return {ok:false,reason:'انتهت صلاحية هذه القسيمة.'};if(subtotal<r.min)return {ok:false,reason:'الحد الأدنى لهذه القسيمة '+amountText(r.min)+'.',...r};return {ok:true,...r};}
function markUsed(code,orderId){ensure();if(String(code||'').trim().toUpperCase()==='FREE100')return;const c=S().couponWallet.find(c=>c.code===String(code||'').trim().toUpperCase());if(c&&!c.usedAt){c.claimed=true;c.usedAt=Date.now();c.orderId=orderId;persist();}}
window.MonarcaAccountCoupons={validate:validateCoupon,markUsed,ensure};

function account(){const s=ensure(),u=s.user,unread=s.notificationRecords.filter(n=>!n.read).length,open=s.tickets.filter(t=>t.status!=='resolved').length;const count=status=>s.orders.filter(o=>status.includes(o.status)).length;return `${top('حسابي',`<button class="icon-btn" data-go="settings" aria-label="الإعدادات">${icon('settings')}</button>`)}<section class="ac-profile-hero"><span class="ac-avatar" data-user-text>${u?esc(u.name?.trim().charAt(0)||'M'):icon('user')}</span><div><small>YOUR MONARCA</small><h2>${u?'أهلاً، <span data-user-text>'+esc(u.name)+'</span>':'مساحة لكل ما تحبين'}</h2><p>${u?`<span class="ltr" data-user-text>${esc(u.phone)}</span>`:'سجّلي دخولك لتكتمل تفاصيلك'}</p></div><button class="ac-hero-action" data-go="${u?'profile':'login'}" aria-label="${u?'تعديل الملف الشخصي':'تسجيل الدخول'}">${u?icon('edit'):'دخول'}</button></section><div class="page-content ac-page"><section class="ac-section"><div class="ac-heading"><h2>طلباتي</h2>${goto('عرض الكل','orders','text-btn')}</div><div class="ac-order-shortcuts">${[['card','بانتظار الدفع',['payment_pending'],'payment_pending'],['box','قيد التجهيز',['placed','preparing'],'preparing'],['truck','في الطريق',['shipped'],'shipped'],['check','مكتملة',['delivered'],'delivered']].map(([i,n,st,f])=>`<button data-action="ac-order-status" data-value="${f}"><span>${icon(i)}${count(st)?`<em>${ar(count(st))}</em>`:''}</span><b>${n}</b></button>`).join('')}</div><p class="ac-caption">تظهر الطلبات المحفوظة على هذا الجهاز، بما فيها طلبات العرض.</p></section><div class="ac-account-stats">${goto(`<b>${ar(s.wish.length)}</b><span>قطعة مفضلة</span>`,'wishlist','ac-stat')}${goto(`<b>${ar(s.couponWallet.filter(c=>c.code!=='FREE100'&&couponStatus(c)==='ready').length)}</b><span>قسائم جاهزة</span>`,'coupons','ac-stat')}${goto(`<b>${ar(unread)}</b><span>إشعارات جديدة</span>`,'notifications','ac-stat')}</div>${section('تفاصيلك',menu('user','الملف الشخصي','الاسم وبيانات التواصل','profile')+menu('pin','دفتر العناوين','عناوين التوصيل والنقاط الدالة','addresses')+menu('card','بطاقاتي','Visa و Mastercard · بطاقات اختبار فقط','payment-methods')+menu('tag','قسائم الخصم','استلمي القسائم واستخدميها في السلة','coupons'))}${section('نحن هنا للمساعدة',whatsappMenu()+menu('return','الإرجاع والاستبدال','طلبات الإرجاع وحالات المعالجة','returns')+menu('card','الاستردادات','متابعة المبالغ التجريبية','refunds')+menu('chat','مركز المساعدة','أسئلة شائعة ومحادثات الدعم','support')+menu('box','طلبات المساعدة','تابعي ردود فريق العناية التجريبي','tickets',open?ar(open):'')+menu('bell','الإشعارات','الطلبات والعروض وأخبار المتجر','notifications',unread?ar(unread):''))}${section('Monarca',menu('info','عن العلامة','تفاصيل بسيطة، وأناقة تدوم','about')+menu('shield','السياسات والخصوصية','تعرفي على قواعد النسخة التجريبية','policy')+menu('settings','إعدادات التطبيق','التفضيلات واللغة وإدارة البيانات','settings'))}${note('نسخة تفاعلية للعرض. تُحفظ بيانات التجربة في هذا المتصفح فقط، ولا تتم مزامنتها بين الأجهزة.')}<div class="app-footer">MONARCA · MADE FOR YOUR EVERYDAY</div></div>`;}
function profile(){const s=ensure();if(!s.user)return `${top('الملف الشخصي')}<div class="page-content ac-page">${head('A PERSONAL TOUCH','تفاصيلك تبدأ من هنا','سجّلي الدخول التجريبي لحفظ الاسم وبيانات ملفك على هذا الجهاز.')}<div class="button-stack">${goto('تسجيل الدخول برقم الهاتف','login')}${goto('العودة إلى حسابي','account','secondary')}</div>${note('يمكنك الاستمرار بالتسوق كضيفة. تسجيل الدخول لا يرسل رمزاً حقيقياً.')}</div>`;const p=s.profile;return `${top('الملف الشخصي')}<div class="page-content ac-page"><div class="ac-profile-heading"><span class="ac-avatar" data-user-text>${esc(s.user.name?.charAt(0)||'M')}</span><div><h2>تفاصيل تجعل التجربة لكِ</h2><p>عدّلي بياناتك في أي وقت.</p></div></div><form id="ac-profile-form"><div class="ac-error" id="ac-profile-error" role="alert" tabindex="-1" hidden></div><label class="field"><span>الاسم الكامل <b>*</b></span><input name="name" value="${esc(s.user.name)}" autocomplete="name" maxlength="60" required placeholder="مثال: سارة أحمد"></label><label class="field"><span>رقم الهاتف</span><input value="${esc(s.user.phone)}" class="ltr" readonly aria-describedby="ac-phone-help"><small id="ac-phone-help">رقم مسجّل في هذه التجربة. لتغييره استخدمي إعدادات الأمان.</small></label><label class="field"><span>البريد الإلكتروني <small>اختياري</small></span><input name="email" type="email" value="${esc(p.email||'')}" autocomplete="email" maxlength="120" placeholder="name@example.com" dir="ltr"></label><div class="ac-form-grid"><label class="field"><span>تاريخ الميلاد <small>اختياري</small></span><input name="birthday" type="date" value="${esc(p.birthday||'')}" max="${new Date().toISOString().slice(0,10)}"></label><label class="field"><span>تفضيل التسوّق</span><select name="style"><option value="">بدون تحديد</option>${[['women','نسائي'],['men','رجالي'],['all','كل المجموعات']].map(([v,n])=>`<option value="${v}" ${p.style===v?'selected':''}>${n}</option>`).join('')}</select></label></div><button class="primary" type="submit">حفظ التغييرات</button></form>${section('المزيد من التفاصيل',menu('shield','الدخول والأمان','تغيير رقم الهاتف وسجل الدخول','security')+menu('pin','عناوين التوصيل','إضافة وتعديل عناوينك','addresses'))}${note('الحقول الاختيارية لا تؤثر في إكمال طلبك. لا تتم مشاركة هذه البيانات مع أي جهة في النموذج.')}</div>`;}

function loginState(){U.acLogin=U.acLogin||{step:'phone',phone:'',expires:0,resendAt:0,attempts:0,lockUntil:0};return U.acLogin;}
function startLogin(phone){const p=M.normalizePhone(phone);if(!p){inlineError('ac-login-error','أدخلي رقم هاتف عراقي صحيحاً: 07 متبوعاً بـ 9 أرقام، أو +964 ثم 7 و9 أرقام.');return;}const l=loginState();Object.assign(l,{step:'otp',phone:p,expires:Date.now()+5*60000,resendAt:Date.now()+30000,attempts:0,lockUntil:0});M.render();}
function login(){ensure();const l=loginState(),locked=l.lockUntil>Date.now(),wait=Math.max(0,Math.ceil((l.resendAt-Date.now())/1000));return `${top(l.step==='otp'?'تحققي من رقمك':'مرحباً بكِ')}<div class="page-content ac-page"><div class="ac-login-symbol">${icon(l.step==='otp'?'shield':'user')}</div>${head('THE MONARCA EXPERIENCE',l.step==='otp'?'خطوة صغيرة وتصلين':'اختياراتك في مكان واحد',l.step==='otp'?`تم تجهيز رمز تحقق تجريبي للرقم <span class="ltr">${esc(l.phone)}</span>.`:'احفظي تفاصيلك وتابعي طلباتك من حساب واحد على هذا الجهاز.')}<div class="ac-demo-panel"><b>تسجيل دخول تجريبي</b><p>${l.step==='otp'?'رمز التحقق للعرض: <strong dir="ltr">1234</strong> · صالح لمدة ٥ دقائق.':'لن نرسل SMS أو نتصل برقمك. يمكنك استخدام 07700000000 للتجربة.'}</p></div><div id="ac-login-error" class="ac-error" role="alert" tabindex="-1" hidden></div>${l.step==='phone'?`<form id="ac-login-phone-form"><label class="field"><span>رقم الهاتف العراقي</span><div class="ac-phone-field"><span>+964</span><input type="tel" name="phone" inputmode="tel" autocomplete="tel-national" maxlength="20" value="${esc(l.phone.replace(/^\+964\s*/,''))}" placeholder="770 000 0000" aria-label="رقم الهاتف العراقي" required></div><small>يمكنك إدخال الرقم بصيغة 07 أو +964.</small></label><label class="checkbox-row"><input type="checkbox" name="consent" required><span>أوافق على <button type="button" class="text-btn" data-go="policy">شروط وخصوصية النسخة التجريبية</button>.</span></label><button class="primary" type="submit">متابعة برقم الهاتف ${icon('arrow')}</button></form>`:`<form id="ac-login-otp-form"><label class="field"><span>رمز التحقق من ٤ أرقام</span><input class="ac-otp-input" name="otp" inputmode="numeric" autocomplete="one-time-code" maxlength="4" required pattern="[0-9٠-٩۰-۹]{4}" placeholder="— — — —" ${locked?'disabled':''}></label><button type="submit" class="primary" ${locked?'disabled':''}>تأكيد وتسجيل الدخول</button></form><div class="ac-resend-line"><button data-action="ac-resend" ${wait||locked?'disabled':''}>إعادة تجهيز الرمز <span id="ac-resend-seconds">${wait?'('+ar(wait)+' ث)':''}</span></button>${btn('تعديل الرقم','ac-edit-phone','text-btn')}</div>${locked?'<p class="ac-error">تجاوزتِ عدد المحاولات. انتظري دقيقة ثم أعيدي تجهيز الرمز.</p>':''}`}${note('لا تتطلب التجربة كلمة مرور، ولا تُجرى أي عملية تحقق فعلية من ملكية رقم الهاتف.','shield')}<div class="button-stack">${goto('متابعة التسوق كضيفة','home','text-btn')}</div></div>`;}
setInterval(()=>{const l=U.acLogin;if(!l||l.step!=='otp'||U.route.split('/')[0]!=='login')return;const wait=Math.max(0,Math.ceil((l.resendAt-Date.now())/1000)),node=document.getElementById('ac-resend-seconds'),button=document.querySelector('[data-action="ac-resend"]');if(node)node.textContent=wait?'('+ar(wait)+' ث)':'';if(button)button.disabled=wait>0||l.lockUntil>Date.now();if(l.lockUntil&&l.lockUntil<=Date.now()){l.lockUntil=0;l.attempts=0;M.render(true);}},1000);

function coupons(){const s=ensure(),filter=U.acCouponTab||'claim',list=s.couponWallet.filter(c=>c.code!=='FREE100'&&couponStatus(c)===filter),labels={claim:'متاحة للاستلام',ready:'جاهزة للاستخدام',used:'مستخدمة',expired:'منتهية'};return `${top('قسائمك')}<div class="page-content ac-page">${head('A LITTLE EXTRA','تفاصيل ألطف لسلتك','استلمي قسيمة، أضيفي اختياراتك، ثم طبّقي الرمز قبل الدفع.')}<form id="ac-coupon-code-form" class="ac-search-form"><input name="code" placeholder="لديك رمز قسيمة؟" aria-label="رمز القسيمة" maxlength="24" dir="ltr" required><button type="submit">إضافة</button></form>${tabs(Object.entries(labels).map(([v,n])=>[v,`${n} (${ar(s.couponWallet.filter(c=>c.code!=='FREE100'&&couponStatus(c)===v).length)})`]),filter,'cp-tab')}${list.length?list.map(c=>{const r=rules[c.code],status=couponStatus(c);return `<article class="ac-coupon ${status==='expired'||status==='used'?'inactive':''}"><div class="ac-coupon-value">${c.code==='FREE100'?icon('truck'):'10%'}<small>${c.code==='FREE100'?'FREE DELIVERY':'MONARCA GIFT'}</small></div><div class="ac-coupon-body"><span class="ac-chip">${labels[status]}</span><h3>${r?.title||'قسيمة المجموعة السابقة'}</h3><p>${r?.description||'قسيمة توضيحية منتهية الصلاحية'}<br>الحد الأدنى: ${r?money(r.min):'—'}</p><div class="ac-coupon-code" dir="ltr">${esc(c.code)}</div><small>${status==='used'?'استُخدمت في '+date(c.usedAt):'صالحة حتى '+date(c.expires)}${c.archivedDemo?' · نموذج أرشيفي':''}</small>${status==='claim'?btn('استلام القسيمة','cp-claim','secondary',`data-id="${esc(c.id)}"`):status==='ready'?btn('استخدام في السلة','cp-apply','primary',`data-id="${esc(c.id)}"`):status==='used'&&c.orderId?goto('عرض الطلب','order/'+esc(c.orderId),'text-btn'):''}</div></article>`;}).join(''):`<div class="ac-mini-empty">${icon('tag')}<h3>لا توجد قسائم ${labels[filter]}</h3><p>${filter==='ready'?'استلمي قسيمة من تبويب «متاحة للاستلام» لتظهر هنا.':filter==='used'?'بعد إكمال الدفع التجريبي تظهر القسائم المستخدمة هنا.':'كل القسائم التي تحمل هذه الحالة تظهر هنا.'}</p>${filter!=='claim'?btn('تصفّحي القسائم المتاحة','cp-tab','text-btn','data-value="claim"'):''}</div>`}${note(freeDeliveryText,'truck')}${section('كيف تعمل قسائمك؟',`<ol class="ac-numbered"><li>قَسيمة واحدة لكل طلب، ويُحسب الحد الأدنى على قيمة المنتجات قبل الخصم.</li><li>M10 تخصم ١٠٪ من المنتجات المؤهلة من ٤٠ USD.</li><li>تُستخدم القسيمة عند تأكيد طلب الدفع عند الاستلام أو نجاح دفع البطاقة. فشل دفع البطاقة لا يستهلكها.</li></ol>`)}${note('قسائم وقواعد عرض قابلة للتجربة، وتحتاج اعتماد المتجر قبل الإطلاق.')}</div>`;}

function notifications(){const s=ensure(),f=U.acNotificationTab||'all',unread=s.notificationRecords.filter(n=>!n.read).length,ns=s.notificationRecords.filter(n=>f==='all'||f==='unread'&&!n.read||n.category===f).sort((a,b)=>b.time-a.time);return `${top('الإشعارات',`<button class="icon-btn" data-go="preferences" aria-label="تفضيلات الإشعارات">${icon('settings')}</button>`)}<div class="page-content ac-page"><div class="ac-heading"><div><h2>كل جديد، في مكانه</h2><p>${ar(unread)} إشعارات غير مقروءة</p></div>${btn('قراءة الكل','nt-readall','text-btn',unread?'':'disabled')}</div>${tabs([['all','الكل'],['orders','الطلبات'],['offers','العروض'],['service','الخدمات'],['unread','غير مقروء']],f,'nt-filter')}${ns.length?ns.map(n=>`<button class="ac-notification ${n.read?'':'unread'}" data-action="nt-open" data-id="${esc(n.id)}"><span class="ac-menu-icon">${icon(n.icon||'bell')}</span><span><span class="ac-notification-meta">${n.category==='orders'?'طلبك':n.category==='offers'?'عروض Monarca':'خدمات Monarca'} · ${date(n.time)}</span><b>${esc(n.title)}</b><p>${esc(n.body)}</p><small>${n.read?'مقروء':'جديد'} ${icon('arrow')}</small></span>${!n.read?'<i class="ac-unread-dot"></i>':''}</button>`).join(''):`<div class="ac-mini-empty">${icon('bell')}<h3>أنتِ على اطلاع</h3><p>لا توجد إشعارات في هذا القسم حالياً.</p>${goto('مواصلة التسوق','home','secondary')}</div>`}${note('إشعارات داخل النموذج فقط. إعداداتك لا تفعّل إشعارات الجهاز أو الرسائل النصية.')}</div>`;}

const faqs=[
{id:'payment',cat:'payment',q:'ما طرق الدفع المتاحة؟',a:'المتوفر في العراق يمكن دفعه عند الاستلام أو ببطاقات Visa و Mastercard. الطلب من الصين والطلب المختلط يحتاجان دفعاً مسبقاً بالبطاقة. جميع عمليات الدفع في هذه النسخة محاكاة.'},
{id:'pay-fail',cat:'payment',q:'ماذا يحدث إذا فشل الدفع؟',a:'يبقى الطلب بانتظار الدفع ويمكن إعادة المحاولة أو اختيار بطاقة اختبار أخرى من تفاصيل الطلب. لا يُخصم مبلغ ولا تُستهلك قسيمة الخصم حتى نجاح الدفع التجريبي.'},
{id:'shipping',cat:'delivery',q:'هل يتم التوصيل إلى مدينتي؟',a:'اختيار منطقة التوصيل ثم إدخال المدينة أو القضاء أو الناحية في دفتر العناوين. المتوفر في العراق يصل خلال نحو يومين، والطلب من الصين خلال ١٥–٢٠ يوماً. رسوم التوصيل التجريبية ٤ USD للطلب، والتوصيل مجاني من ٧٥ USD قبل الخصم.'},
{id:'tracking',cat:'delivery',q:'كيف أتابع طلبي؟',a:'افتحي حسابي ← طلباتي ← اختاري الطلب ← تتبّع الطلب. تُعرض مراحل تجهيز الطلب والشحن والتسليم. جميع تحديثات الشحنة في هذه النسخة محاكاة.'},
{id:'address',cat:'delivery',q:'ما تفاصيل العنوان المطلوبة؟',a:'الاسم، رقم هاتف عراقي، المحافظة، الحي، الشارع، وأقرب نقطة دالة. يمكن إضافة البناية والطابق وملاحظات للسائق. يُفضّل تأكيد العنوان قبل الدفع.'},
{id:'return',cat:'returns',q:'كيف أطلب إرجاع قطعة؟',a:'بعد وصول الطلب إلى «تم التسليم»، افتحي تفاصيله واختاري طلب إرجاع. حدّدي القطعة والكمية والسبب، ثم تابعي حالة الطلب. الإرجاع في هذه النسخة محاكاة، ومدته وشروطه بانتظار اعتماد المتجر.'},
{id:'cancel',cat:'returns',q:'هل يمكن إلغاء طلبي؟',a:'تُتاح تجربة إلغاء الطلب قبل الشحن. بعد بدء الشحن توجهي إلى الدعم، وبعد التسليم استخدمي طلب الإرجاع. راجعي الحالة الظاهرة في تفاصيل طلبك لمعرفة الإجراء المتاح.'},
{id:'coupon',cat:'shopping',q:'كيف أستخدم قسيمة الخصم؟',a:'من حسابي ← قسائمك، استلمي القسيمة واضغطي «استخدام في السلة». يُطبق رمز واحد لكل طلب عند بلوغ الحد الأدنى، ويُحسب الخصم قبل الدفع. لا تُستخدم القسيمة المنتهية أو المستخدمة.'},
{id:'sizes',cat:'shopping',q:'كيف أختار المقاس المناسب؟',a:'افتحي دليل المقاسات في صفحة المنتج، ثم اختاري المقاس واللون قبل الإضافة. المقاسات غير المتاحة لا يمكن اختيارها. جداول هذه النسخة توضيحية وتحتاج تأكيد بيانات المورّد.'},
{id:'photo',cat:'shopping',q:'كيف يعمل البحث بالصورة؟',a:'اضغطي أيقونة الكاميرا أعلى يسار الصفحة الرئيسية، ثم ارفعي صورة واضحة لقطعة واحدة أو التقطي صورة. النتائج محاكاة لقطع مشابهة داخل الكتالوج، ولا تُرفع الصورة إلى خادم.'},
{id:'login',cat:'account',q:'لم يصلني رمز تسجيل الدخول',a:'لا يتم إرسال SMS في النموذج. بعد إدخال رقم عراقي صحيح استخدمي الرمز 1234. يمكنك إعادة تجهيز الرمز بعد انتهاء العداد. يمتد الرمز التجريبي لمدة ٥ دقائق.'},
{id:'privacy',cat:'account',q:'أين تُحفظ بياناتي؟',a:'تُحفظ السلة والملف والطلبات ومحادثات الدعم محلياً في هذا المتصفح. لا توجد مزامنة أو حساب حقيقي. من الإعدادات يمكن مسح بيانات التجربة وإعادتها إلى البداية.'}
];
const faqCats=[['all','كل الأسئلة'],['shopping','التسوّق'],['payment','الدفع'],['delivery','التوصيل'],['returns','الإرجاع'],['account','الحساب']];
function faq(){ensure();const q=String(U.acFAQQuery||'').trim(),f=U.acFAQCategory||'all',qs=faqs.filter(x=>(f==='all'||x.cat===f)&&(!q||(x.q+' '+x.a).includes(q)));return `${top('الأسئلة الشائعة')}<div class="page-content ac-page">${head('HERE TO HELP','إجابات تريح بالك','كل ما تحتاجينه قبل الطلب وبعده.')}<form id="ac-faq-search-form" class="ac-search-form"><input name="query" value="${esc(q)}" placeholder="ابحثي: الدفع، التوصيل، المقاسات..." aria-label="البحث في المساعدة" maxlength="100"><button type="submit" aria-label="بحث">${icon('search')}</button></form>${tabs(faqCats,f,'help-faq-category')}${q?`<div class="ac-heading"><small>${ar(qs.length)} نتائج لـ «${esc(q)}»</small>${btn('مسح البحث','help-clear-search','text-btn')}</div>`:''}<div class="ac-faq-list">${qs.length?qs.map(x=>`<details class="ac-faq" id="ac-faq-${x.id}" ${U.acFAQOpen===x.id?'open':''}><summary>${x.q}${icon('plus')}</summary><p>${x.a}</p></details>`).join(''):`<div class="ac-mini-empty">${icon('search')}<h3>لم نجد إجابة مطابقة</h3><p>جرّبي عبارة أقصر أو اختاري قسماً آخر، ويمكنك فتح طلب مساعدة.</p>${goto('إنشاء طلب مساعدة','ticket/new','secondary')}</div>`}</div>${section('تحتاجين مساعدة أكثر؟',`<p class="ac-lead">اشرحي المشكلة وأضيفي رقم الطلب إن وجد، وستبقى المحادثة محفوظة على جهازك.</p><div class="button-stack">${goto('تحدثي مع العناية التجريبية','ticket/new')}${goto('طلباتي في الدعم','tickets','secondary')}</div>`)}</div>`;}
function whatsappMenu(){const d=M.contactDetails();return `<button type="button" class="store-contact-menu" data-action="store-contact" data-context="general"><span class="ac-menu-icon">${icon('whatsapp')}</span><span><b>التواصل عبر واتساب</b><small>${d.mode==='demo'?'رقم توضيحي · ':''}<span class="ltr">${esc(d.numberText)}</span></small></span>${icon('arrow')}</button>`;}
function whatsappCard(){const d=M.contactDetails(),demo=d.mode==='demo';return `<section class="store-contact-card"><div class="store-contact-heading">${icon('whatsapp')}<div><h2>Monarca على واتساب</h2><small>تواصلي مع المتجر</small></div></div><p>للاستفسار عن المنتجات والطلبات، تواصلي مع متجر Monarca عبر واتساب.</p><div class="store-contact-number"><span>${demo?'رقم توضيحي للعرض':'رقم المتجر'}</span><b class="ltr">${esc(d.numberText)}</b></div>${demo?'<small class="store-contact-demo">معاينة فقط · يُفعّل الرابط بعد اعتماد رقم المتجر.</small>':''}${M.contactButton(demo?'معاينة التواصل عبر واتساب':'التواصل عبر واتساب')}</section>`;}
function support(){const s=ensure(),open=s.tickets.filter(t=>t.status!=='resolved'),latest=s.tickets.slice().sort((a,b)=>b.updated-a.updated)[0];return `${top('مركز العناية')}<div class="page-content ac-page">${head('THE MONARCA CARE','يسعدنا أن نكون بقربك','اختاري الموضوع أو ابدئي محادثة، وستجدين كل التفاصيل في مكان واحد.')}<form id="ac-faq-search-form" class="ac-search-form"><input name="query" placeholder="كيف يمكننا مساعدتك؟" aria-label="البحث في المساعدة" maxlength="100"><button type="submit" aria-label="بحث">${icon('search')}</button></form><div class="ac-care-grid">${[['box','طلبي وتتبّعه','delivery'],['card','الدفع والبطاقات','payment'],['return','الإرجاع والإلغاء','returns'],['bag','المنتجات والمقاسات','shopping']].map(([i,t,c])=>`<button data-action="help-topic" data-value="${c}">${icon(i)}<b>${t}</b>${icon('arrow')}</button>`).join('')}</div>${section('إجابات سريعة',faqs.filter(f=>['payment','shipping','return','photo'].includes(f.id)).map(f=>`<button class="ac-faq-link" data-action="help-open-faq" data-id="${f.id}">${f.q}${icon('arrow')}</button>`),goto('الكل','faq','text-btn'))}${whatsappCard()}<section class="ac-care-card"><span>${icon('chat')}</span><small>خدمة داخل التطبيق · محاكاة</small><h2>لنرتّب التفاصيل معاً</h2><p>افتحي طلباً جديداً، أو تابعي محادثة سابقة من مركز العناية.</p>${goto('محادثة تجريبية داخل التطبيق','ticket/new')}${goto('طلبات المساعدة'+(open.length?' · '+ar(open.length)+' مفتوحة':''),'tickets','text-btn')}</section>${latest?`<button class="ac-ticket-preview" data-go="ticket/${esc(latest.id)}"><span><small>آخر محادثة · ${date(latest.updated)}</small><b><span data-user-text>${esc(latest.subject)}</span></b><p>${latest.status==='resolved'?'تم حل الطلب':'متابعة المحادثة'}</p></span>${icon('arrow')}</button>`:''}${note('محادثات المساعدة داخل التطبيق محاكاة محلية بردود آلية، ولا تُرسل إلى موظف. التواصل عبر واتساب منفصل ويفتح خارج التطبيق بعد اعتماد رقم المتجر؛ أنتِ من ترسلين الرسالة. لا تمثل هذه النسخة ساعات عمل أو وعداً بوقت استجابة.','chat')}</div>`;}
function ticketNew(){const s=ensure(),orderId=U.acSupportOrder||'',type=U.acSupportType||'order';return `${top('طلب مساعدة جديد')}<div class="page-content ac-page">${head('TELL US THE DETAILS','لنتابع الأمر خطوة بخطوة','أضيفي التفاصيل التي تساعدنا على فهم طلبك.')}<form id="ac-ticket-new-form"><div class="ac-error" id="ac-ticket-error" role="alert" tabindex="-1" hidden></div><label class="field"><span>موضوع المساعدة <b>*</b></span><select name="type">${[['order','متابعة طلب'],['payment','مشكلة في الدفع'],['return','إرجاع أو استبدال'],['product','استفسار عن منتج'],['account','الحساب والعناوين'],['other','موضوع آخر']].map(([v,t])=>`<option value="${v}" ${type===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field"><span>الطلب المرتبط <small>اختياري</small></span><select name="order"><option value="">بدون طلب مرتبط</option>${s.orders.map(o=>`<option value="${esc(o.id)}" ${orderId===o.id?'selected':''}>${esc(o.id)}${o.sample?' · عرض':''}</option>`).join('')}</select></label><label class="field"><span>عنوان مختصر <b>*</b></span><input name="subject" required minlength="4" maxlength="90" placeholder="مثال: أحتاج مساعدة في اختيار المقاس"></label><label class="field"><span>التفاصيل <b>*</b></span><textarea name="message" required minlength="10" maxlength="1200" rows="5" placeholder="اشرحي ما حدث، وما المساعدة التي تحتاجينها..."></textarea><small>١٠–١٢٠٠ حرف. لا تضيفي بيانات البطاقة أو رمز التحقق.</small></label><button type="submit" class="primary">إنشاء المحادثة ${icon('send')}</button></form>${note('طلب دعم تجريبي، محفوظ في هذا المتصفح. ستظهر إجابة آلية لتوضيح رحلة خدمة العميل.')}</div>`;}
function tickets(){const s=ensure(),f=U.acTicketTab||'all',list=s.tickets.filter(t=>f==='all'||t.status===f).slice().sort((a,b)=>b.updated-a.updated);return `${top('طلبات المساعدة',`<button class="icon-btn" data-go="ticket/new" aria-label="طلب جديد">${icon('plus')}</button>`)}<div class="page-content ac-page">${head('YOUR CONVERSATIONS','كل محادثة، محفوظة','تابعي ردود العناية، واطّلعي على سجل طلباتك.')}<div class="ac-demo-inline">${icon('info')} محادثات تجريبية · لا اتصال بدعم فعلي</div>${tabs([['all','الكل'],['open','مفتوحة'],['resolved','تم حلّها']],f,'help-ticket-filter')}${list.length?list.map(t=>`<button class="ac-ticket-row" data-go="ticket/${esc(t.id)}"><div class="ac-heading"><span class="ltr">${esc(t.id)}</span><span class="ac-chip ${t.status==='resolved'?'success':''}">${t.status==='resolved'?'تم الحل':'مفتوح'}</span></div><h3><span data-user-text>${esc(t.subject)}</span></h3><p><span data-user-text>${esc(t.messages[t.messages.length-1]?.text||'')}</span></p><small>${t.orderId?'الطلب '+esc(t.orderId)+' · ':''}${date(t.updated,true)} · ${ar(t.messages.length)} رسائل</small></button>`).join(''):`<div class="ac-mini-empty">${icon('chat')}<h3>${f==='resolved'?'لا توجد محادثات محلولة بعد':'لا توجد محادثات هنا'}</h3><p>يمكنك بدء طلب مساعدة جديد، وستظهر متابعة المحادثة هنا.</p>${goto('إنشاء طلب مساعدة','ticket/new','secondary')}</div>`}</div>`;}
function ticket(id){ensure();if(id==='new'||!id)return ticketNew();const t=S().tickets.find(x=>x.id===id);if(!t)return `${top('طلب المساعدة')}<div class="page-content ac-page">${M.empty('لم نجد هذه المحادثة','ربما مُسحت بيانات التجربة. يمكنك إنشاء طلب جديد.','chat','عرض طلبات المساعدة','tickets')}</div>`;return `${top('محادثتك مع العناية',goto('كل الطلبات','tickets','text-btn'))}<div class="ac-demo-inline">${icon('info')} ردود آلية للتجربة · لا تُرسَل لأي موظف</div><div class="ac-ticket-header"><div class="ac-heading"><span class="ltr">${esc(t.id)}</span><span class="ac-chip ${t.status==='resolved'?'success':''}">${t.status==='resolved'?'تم الحل':'مفتوح'}</span></div><h2><span data-user-text>${esc(t.subject)}</span></h2><p>أُنشئت ${date(t.created,true)}</p>${t.orderId?goto('الطلب '+esc(t.orderId),'order/'+esc(t.orderId),'text-btn'):''}</div><div class="ac-conversation">${t.messages.map(m=>`<div class="ac-message ${m.mine?'mine':''}"><small>${m.mine?'أنتِ':'العناية · رد آلي'} · ${date(m.time,true)}</small><p>${esc(m.text).replace(/\n/g,'<br>')}</p></div>`).join('')}${U.acReplyPending===t.id?'<div class="ac-message"><small>العناية التجريبية</small><p>جارٍ تجهيز الرد التوضيحي…</p></div>':''}</div>${t.status==='resolved'?`<div class="page-content ac-page">${note('أُغلقت المحادثة بناءً على اختيارك. يمكنك إعادة فتحها إذا احتجتِ متابعة.','check')}${btn('إعادة فتح المحادثة','help-reopen','secondary',`data-id="${esc(t.id)}"`)}</div>`:`<form id="ac-ticket-reply-form" class="ac-chat-compose" data-id="${esc(t.id)}"><label class="sr-only" for="ac-reply-input">رسالتك</label><textarea id="ac-reply-input" name="message" maxlength="1200" rows="2" placeholder="اكتبي رسالتك..." required ${U.acReplyPending===t.id?'disabled':''}></textarea><button type="submit" aria-label="إرسال الرسالة" ${U.acReplyPending===t.id?'disabled':''}>${icon('send')}</button></form><div class="page-content ac-page ac-ticket-tools">${btn('تم حل المشكلة','help-resolve','secondary',`data-id="${esc(t.id)}"`)}${goto('الأسئلة الشائعة','faq','text-btn')}<p class="ac-caption">لا تشاركي بيانات البطاقة أو رموز التحقق في الرسائل.</p></div>`}`;}
function automatedReply(t,text){const bodies={payment:'يمكن اختيار Visa أو Mastercard للقسمين، أو الدفع عند الاستلام للمتوفر في العراق فقط. الطلب من الصين والطلب المختلط يحتاجان دفعاً مسبقاً بالبطاقة. معلومات التوصيل والدفع في صفحة واحدة. البطاقة تستخدم بيانات الاختبار فقط، ولا يتم خصم أموال.',return:'يمكن طلب إرجاع من تفاصيل الطلب بعد التسليم، مع تحديد القطعة والكمية والسبب. شروط المدة والأهلية النهائية تحتاج اعتماد المتجر قبل الإطلاق.',product:'تجدين المقاسات والألوان المتاحة ودليل القياس في صفحة المنتج. المقاسات المشطوبة غير متاحة، ويمكن حفظ القطعة في المفضلة للرجوع إليها.',account:'يمكن تعديل الاسم والبريد من الملف الشخصي، والعناوين من دفتر العناوين. جميع البيانات محلية على هذا الجهاز.'};if(/شحن|توصيل|وصل|طلب/.test(text)||t.type==='order')return 'متابعة التجهيز والشحن من «حسابي ← طلباتي». المتوفر في العراق يصل خلال نحو يومين، والطلب من الصين خلال ١٥–٢٠ يوماً. الطلب المختلط يصل على شحنتين. تحديثات التتبع محاكاة.';return bodies[t.type]||'وصلت رسالتك في المحادثة التجريبية. يمكنك مراجعة الأسئلة الشائعة أو إرفاق رقم الطلب من طلب مساعدة جديد. هذه إجابة آلية لعرض تصميم خدمة العميل.';}
function replyLater(id,text){U.acReplyPending=id;setTimeout(()=>{ensure();const t=S().tickets.find(t=>t.id===id);if(t){t.messages.push({mine:false,text:automatedReply(t,text),time:Date.now()});t.updated=Date.now();S().notificationRecords.unshift({id:'support-'+Date.now(),category:'service',title:'رد جديد من العناية التجريبية',body:t.subject,route:'ticket/'+t.id,icon:'chat',read:U.route==='ticket/'+id,time:Date.now()});persist();}if(U.acReplyPending===id)U.acReplyPending=null;if(U.route==='ticket/'+id)M.render(true);},700);}

function settings(){const s=ensure();return `${top('الإعدادات')}<div class="page-content ac-page">${head('THE LITTLE DETAILS','اضبطي تجربتك','إعدادات واضحة تناسب طريقة تسوّقك.')} ${section('التفضيلات',menu('bell','تفضيلات الإشعارات','الطلبات والعروض وخدمة العملاء','preferences')+menu('globe','اللغة والمنطقة','العربية · العراق · USD','region'))}${section('الخصوصية والحساب',menu('shield','الدخول والأمان','الرقم والجلسة التجريبية','security')+menu('user','البيانات الشخصية','مراجعة وتعديل الملف','profile')+menu('shield','الخصوصية والسياسات','بياناتك وكيف تعمل النسخة','policy'))}${section('التخزين على هذا الجهاز',`<p class="ac-lead">بياناتك محفوظة محلياً. مسح الملفات المؤقتة يزيل سجل البحث والتفضيلات المؤقتة، وتبقى السلة والطلبات والعناوين.</p><div class="button-stack">${btn('مسح الملفات المؤقتة','ac-clear-cache','secondary')}${btn('إعادة ضبط جميع بيانات التجربة','reset','text-btn')}</div>`)}${section('عن التطبيق',menu('info','عن Monarca','إصدار النموذج 4.7','about'))}${s.user?`<div class="button-stack">${btn(icon('logout')+' تسجيل الخروج','ac-signout','secondary')}</div>`:goto('تسجيل الدخول','login')}<div class="app-footer">MONARCA · PROTOTYPE 4.7 · IRAQ</div></div>`;}
function preferencesView(){const s=ensure();return `${top('تفضيلات الإشعارات')}<div class="page-content ac-page">${head('STAY IN THE KNOW','اخبريـنا ما يهمّك','هذه الإعدادات تتحكم في التفضيل المحفوظ داخل النموذج.')} ${[['orders','حالة الطلبات','تأكيد الطلب والشحن والتسليم.'],['offers','العروض والمجموعات','القسائم والمختارات الجديدة.'],['services','خدمة العملاء','الردود وتحديثات طلبات المساعدة.']].map(([id,n,t])=>`<button class="ac-toggle-row" data-action="ac-preference" data-key="${id}" aria-pressed="${!!s.notificationPreferences[id]}"><span><b>${n}</b><small>${t}</small></span><i class="toggle ${s.notificationPreferences[id]?'on':''}" aria-hidden="true"></i></button>`).join('')}${note('لا تُفعّل هذه الخيارات إشعارات النظام أو البريد أو SMS. سجل الإشعارات داخل التطبيق يبقى متاحاً لمراجعة أحداث التجربة.')}<div class="button-stack">${goto('عرض مركز الإشعارات','notifications','secondary')}</div></div>`;}
function region(){return `${top('اللغة والمنطقة')}<div class="page-content ac-page">${head('MADE FOR IRAQ','تجربة قريبة منكِ','تُعرض هذه النسخة باللغة العربية ومن اليمين إلى اليسار.')}<div class="ac-setting-info"><span>${icon('globe')}</span><div><small>اللغة الحالية</small><h3>العربية</h3><p>واجهة كاملة باتجاه RTL</p></div><span class="ac-chip success">مفعّلة</span></div><div class="ac-setting-info"><span>${icon('pin')}</span><div><small>بلد التوصيل</small><h3>العراق</h3><p>رقم الهاتف الدولي +964</p></div></div><div class="ac-setting-info"><span>${icon('tag')}</span><div><small>عملة العرض والدفع التجريبي</small><h3>الدولار الأمريكي</h3><p dir="ltr">USD · $</p></div></div>${note('يدعم التطبيق العربية والإنجليزية. بلد التوصيل العراق، والأسعار بالدولار الأمريكي USD.')}${goto('إدارة عناوين التوصيل','addresses','secondary')}</div>`;}
function security(){const s=ensure();return `${top('الدخول والأمان')}<div class="page-content ac-page">${head('YOUR ACCOUNT, SIMPLY','وضوح في كل خطوة','دخول برقم عراقي ورمز تحقق تجريبي.')}<div class="ac-setting-info"><span>${icon('user')}</span><div><small>حالة الحساب</small><h3>${s.user?'تم الدخول التجريبي':'التصفح كضيفة'}</h3><p dir="ltr">${s.user?esc(s.user.phone):'—'}</p></div></div>${s.user?`<div class="button-stack">${btn('تغيير رقم الهاتف','ac-change-phone','secondary')}${btn('تسجيل الخروج من هذه الجلسة','ac-signout','text-btn')}</div>`:goto('تسجيل الدخول','login')}${section('نشاط الدخول على هذا الجهاز',s.security.loginRecords.length?s.security.loginRecords.slice(0,5).map(r=>`<div class="ac-login-record">${icon('shield')}<span><b>دخول تجريبي من هذا المتصفح</b><small>${date(r.time,true)} · <span class="ltr">${esc(r.phone)}</span></small></span><em>محلي</em></div>`).join(''):'<p class="ac-lead">لا يوجد نشاط دخول تجريبي محفوظ بعد.</p>')}${note('لا تمثل الجلسة تحققاً حقيقياً من الهوية. لا توجد كلمات مرور أو جلسات على خادم، والرمز المعروض للشرح فقط.')}<div class="button-stack">${goto('الخصوصية والبيانات','policy','secondary')}</div></div>`;}

function cardMark(network){return network==='mastercard'?'<span class="mastercard-mark" aria-label="Mastercard"><i></i><i></i></span>':'<span class="visa-mark">VISA</span>';}
function paymentMethods(){const s=ensure();return `${top('بطاقاتي')}<div class="page-content ac-page">${head('PAYMENT, CONSIDERED','بطاقة جاهزة للتجربة','اختاري بطاقة اختبار لاستخدامها في عرض خطوات الدفع.')}<div class="ac-demo-panel"><b>بطاقات اختبار فقط</b><p>لا تدخلي أي رقم بطاقة حقيقي. نحفظ نوع البطاقة وآخر ٤ أرقام ومعرّفاً تجريبياً فقط، دون رقم البطاقة الكامل أو رمز الأمان.</p></div>${s.paymentTokens.length?s.paymentTokens.map(t=>`<article class="ac-bank-card"><div class="ac-heading">${cardMark(t.network)}<span class="ac-chip">${t.default?'الافتراضية':'بطاقة اختبار'}</span></div><p class="ac-masked-pan" dir="ltr">•••• &nbsp; •••• &nbsp; •••• &nbsp; ${esc(t.last4)}</p><div class="ac-heading"><div><b>${esc(t.holder||'MONARCA DEMO')}</b><small>${t.network==='visa'?'Visa':'Mastercard'} · اختبار</small></div><div class="ac-card-actions">${!t.default?btn('تعيين افتراضية','ac-card-default','text-btn',`data-id="${esc(t.id)}"`):''}${btn(icon('trash'),'ac-card-remove','icon-btn',`data-id="${esc(t.id)}" aria-label="حذف بطاقة الاختبار"`)}</div></div></article>`).join(''):`<div class="ac-mini-empty">${icon('card')}<h3>لا توجد بطاقات محفوظة</h3><p>أضيفي بطاقة اختبار، أو اختاريها عند إكمال الطلب.</p></div>`}<div class="button-stack">${btn(icon('plus')+' إضافة بطاقة اختبار','ac-card-add','secondary')}</div>${section('طرق الدفع المعتمدة للتصميم',`<div class="ac-network-row">${cardMark('visa')}${cardMark('mastercard')}<span>Visa · Mastercard</span></div><p class="ac-lead">الدفع عند الاستلام متاح للمنتجات المتوفرة في المتجر فقط. الطلب المسبق يحتاج بطاقة. بوابة الدفع والتحقق الفعلي لم يُربطا بعد.</p>`)}${goto('مواصلة التسوق','home','text-btn')}</div>`;}
function addCardSheet(){M.sheet('إضافة بطاقة اختبار',`<div class="ac-demo-panel"><b>اختاري البطاقة الجاهزة</b><p>لا نطلب إدخال رقم بطاقة أو CVV هنا. البطاقتان بيانات اختبار ثابتة.</p></div><form id="ac-card-add-form"><label class="field"><span>نوع البطاقة</span><select name="network"><option value="visa">Visa · •••• 4242</option><option value="mastercard">Mastercard · •••• 4444</option></select></label><label class="field"><span>اسم توضيحي للبطاقة</span><input name="holder" maxlength="60" placeholder="مثال: بطاقتي التجريبية" value="MONARCA DEMO"></label><label class="checkbox-row"><input type="checkbox" name="default" checked><span>استخدامها افتراضياً في الدفع التجريبي</span></label><button type="submit" class="primary">حفظ بطاقة الاختبار</button></form>`);}

function policy(){return `${top('السياسات والخصوصية')}<div class="page-content ac-page">${head('CLEAR BY DESIGN','كل التفاصيل بوضوح','وثيقة شرح للنموذج، وليست شروط متجر نهائية أو استشارة قانونية.')}<div class="ac-policy-index">${[['intro','حول النموذج'],['payment','الدفع والطلبات'],['delivery','التوصيل'],['returns','الإرجاع والاسترداد'],['data','الخصوصية والبيانات']].map(([i,n])=>`<button data-action="ac-policy-jump" data-value="${i}">${n}${icon('arrow')}</button>`).join('')}</div><section class="ac-policy-block" id="ac-policy-intro"><div>${icon('info')}</div><small>01 · THE EXPERIENCE</small><h2>حول هذه النسخة</h2><p>Monarca نموذج تفاعلي للسوق العراقي لعرض التصميم ومسارات التسوّق. المنتجات والأسعار والمخزون والتقييمات والقسائم بيانات توضيحية، ولا تُنشئ عملية شراء فعلية. يجب اعتماد بيانات المتجر وسياساته ووسائل التواصل قبل الإطلاق.</p></section><section class="ac-policy-block" id="ac-policy-payment"><div>${icon('card')}</div><small>02 · PAYMENT & ORDERS</small><h2>الدفع والطلبات</h2><p>الدفع ببطاقات Visa و Mastercard للقسمين، أو الدفع عند الاستلام للمتوفر في العراق فقط. الطلب من الصين والطلب المختلط يحتاجان دفعاً مسبقاً بالبطاقة. هذه محاكاة لا تخصم أموالاً ولا تتصل بمصرف أو مندوب. معلومات العنوان والدفع في صفحة واحدة. لا تُدخل بيانات بطاقة حقيقية أو رموز مصرفية.</p><p>تُحفظ البطاقة كمعرّف اختبار ونوعها وآخر ٤ أرقام فقط. الطلبات والتغييرات والإلغاءات تبقى داخل هذا المتصفح.</p></section><section class="ac-policy-block" id="ac-policy-delivery"><div>${icon('truck')}</div><small>03 · DELIVERY</small><h2>التوصيل داخل العراق</h2><p>المتوفر في العراق يصل خلال نحو يومين، ويمكن الدفع عند الاستلام أو بالبطاقة. الطلب من الصين يحتاج ١٥–٢٠ يوماً ودفعاً مسبقاً بالبطاقة. الطلب المختلط يصل على شحنتين ويحتاج بطاقة. رسوم التوصيل التجريبية ٤ USD للطلب، والتوصيل مجاني من ٧٥ USD قبل الخصم.</p><p>منطقة التوصيل والمدينة أو القضاء والحي والشارع والنقطة الدالة مطلوبة لتوضيح تجربة إعداد عنوان عراقي. لا تُرسل العناوين إلى شركة شحن.</p></section><section class="ac-policy-block" id="ac-policy-returns"><div>${icon('return')}</div><small>04 · RETURNS & REFUNDS</small><h2>الإلغاء والإرجاع والاسترداد</h2><p>يمكن اختبار الإلغاء قبل الشحن، وطلب الإرجاع للقطع بعد التسليم، ثم متابعة حالته. جميع الحالات واستردادات المبالغ محاكاة. لا توجد حركة مالية حقيقية.</p><p>المدة المسموحة للإرجاع، القطع المستثناة، حالة التغليف، رسوم الشحن، وآلية ومدة الاسترداد تحتاج اعتماد المتجر قبل تشغيل الخدمة.</p>${goto('كيف أطلب إرجاعاً؟','faq','text-btn')}</section><section class="ac-policy-block" id="ac-policy-data"><div>${icon('shield')}</div><small>05 · YOUR DATA</small><h2>خصوصيتك وبياناتك</h2><p>تُحفظ السلة والمفضلة والملف والطلبات والعناوين والتذاكر محلياً في تخزين المتصفح. لا توجد قاعدة بيانات أو مزامنة بين الأجهزة. تسجيل الدخول لا يرسل SMS ولا يؤكد ملكية الهاتف فعلياً.</p><p>صور البحث المختارة تُستخدم في الجلسة المحلية ولا تُرفع إلى خادم في النموذج. الردود والإشعارات آلية. الصور البصرية مقدمة كمرجع من العميل أو مولّدة لأغراض التصميم.</p><p>مسح بيانات المتصفح أو إعادة ضبط التجربة يزيل المعلومات المحلية. قد لا تتوفر إمكانية الاسترداد بعد المسح.</p><div class="button-stack">${goto('إدارة البيانات والإعدادات','settings','secondary')}</div></section><div class="ac-policy-footer"><b>قبل الإطلاق الفعلي</b><p>تُعتمد هوية البائع وبيانات التواصل والسياسات وبيانات المنتجات، ثم تُربط خدمات الدخول والدفع والشحن والدعم وتُختبر في بيئة تشغيل مناسبة.</p></div>${goto('التواصل مع العناية التجريبية','support','secondary')}</div>`;}
function about(){return `${top('عن Monarca')}<div class="ac-about-cover"><span class="brandmark" role="img" aria-label="Monarca"></span><small>DETAILS THAT BECOME YOU</small><h2>أناقة ترافق تفاصيلك.</h2><p>اختيارات هادئة، وخامات مُلهمة،<br>وقطع تكمّل كل يوم بطريقتك.</p></div><div class="page-content ac-page">${section('عالم Monarca',`<p class="ac-lead">مساحة للتسوّق تجمع الملابس والحقائب والأحذية والإكسسوارات في تجربة عربية مصممة للعراق. من القطعة التي تلهمك إلى تفاصيل وصولها، كل خطوة لها مكان واضح.</p>`)}<div class="ac-brand-values">${[['heart','اختيارات بعناية','اكتشفي مجموعات تناسب يومك.'],['pin','قريبة منكِ','واجهة عربية وعناوين عراقية.'],['chat','العناية بالتفاصيل','مساعدة واضحة قبل الطلب وبعده.']].map(([i,t,p])=>`<div>${icon(i)}<h3>${t}</h3><p>${p}</p></div>`).join('')}</div><div class="button-stack">${goto('استكشفي المجموعات','categories')}${goto('مركز العناية','support','secondary')}</div>${note('نص تعريفي مقترح للتصميم، ويحتاج اعتماد العلامة قبل النشر. لا يتضمن ادعاءات عن تاريخ الشركة أو منشأ المنتجات.')}<div class="ac-about-meta"><span>Monarca · العراق</span><span>Interactive Prototype · 4.4</span></div></div>`;}

const actions={
'ac-order-status':el=>{U.orderFilter=el.dataset.value;M.go('orders');},
'ac-edit-phone':()=>{loginState().step='phone';M.render();},
'ac-resend':()=>{const l=loginState();if(l.resendAt>Date.now()||l.lockUntil>Date.now())return;Object.assign(l,{resendAt:Date.now()+30000,expires:Date.now()+5*60000,attempts:0});M.render(true);M.toast('تم تجهيز رمز التجربة 1234. لم تُرسل SMS.');},
'ac-signout':()=>{M.sheet('تسجيل الخروج',`<p>سيُزال دخولك التجريبي من هذا الجهاز. تبقى السلة والمفضلة والطلبات والعناوين المحلية محفوظة.</p><div class="button-stack">${btn('تأكيد تسجيل الخروج','ac-signout-confirm')}${btn('العودة للحساب','close-sheet','secondary')}</div>`);},
'ac-signout-confirm':()=>{ensure();S().user=null;persist();M.closeSheet();M.go('account');M.toast('تم تسجيل الخروج التجريبي');},
'ac-change-phone':()=>{M.sheet('تغيير رقم الهاتف',`<p>ستعودين لخطوة الدخول وتتحققين برمز العرض 1234. بيانات التسوّق المحلية تبقى محفوظة، ولا يتم تغيير هاتف عنوان التوصيل تلقائياً.</p><div class="button-stack">${btn('متابعة لتغيير الرقم','ac-change-phone-confirm')}${btn('إلغاء','close-sheet','secondary')}</div>`);},
'ac-change-phone-confirm':()=>{U.acLogin={step:'phone',phone:'',expires:0,resendAt:0,attempts:0,lockUntil:0};U.acChangingPhone=true;M.closeSheet();M.go('login');},
'ac-clear-cache':()=>{M.sheet('مسح الملفات المؤقتة',`<p>سيتم مسح سجل البحث وتصفية المنتجات والخيارات المؤقتة. تبقى السلة والطلبات والعناوين والملف ومحادثات الدعم محفوظة.</p><div class="button-stack">${btn('مسح الملفات المؤقتة','ac-clear-cache-confirm')}${btn('إلغاء','close-sheet','secondary')}</div>`);},
'ac-clear-cache-confirm':()=>{ensure();S().searchHistory=[];S().recentSearches=[];S().recentlyViewed=[];U.query='';U.category='all';U.max=M.commerce.priceCeiling;U.sort='recommended';U.catalogFilter={sub:'all',min:0,max:M.commerce.priceCeiling,color:'all',size:'all',stock:false};U.acFAQQuery='';U.acFAQCategory='all';U.acNotificationTab='all';U.acTicketTab='all';U.acCouponTab='claim';persist();M.closeSheet();M.render(true);M.toast('تم مسح الملفات المؤقتة');},
'ac-preference':el=>{ensure();const key=el.dataset.key;if(!(key in preferences))return;S().notificationPreferences[key]=!S().notificationPreferences[key];persist();M.render(true);},
'ac-card-add':addCardSheet,
'ac-card-default':el=>{ensure();const id=el.dataset.id;if(!S().paymentTokens.some(t=>t.id===id))return;S().paymentTokens.forEach(t=>t.default=t.id===id);persist();M.render(true);M.toast('تم تغيير بطاقة الاختبار الافتراضية');},
'ac-card-remove':el=>{const id=el.dataset.id;M.sheet('حذف بطاقة الاختبار',`<p>ستُزال البطاقة من قائمة البطاقات المحفوظة فقط. تبقى تفاصيل طلباتك السابقة محفوظة.</p><div class="button-stack">${btn('حذف البطاقة','ac-card-remove-confirm','primary',`data-id="${esc(id)}"`)}${btn('إلغاء','close-sheet','secondary')}</div>`);},
'ac-card-remove-confirm':el=>{ensure();S().paymentTokens=S().paymentTokens.filter(t=>t.id!==el.dataset.id);if(S().paymentTokens.length&&!S().paymentTokens.some(t=>t.default))S().paymentTokens[0].default=true;persist();M.closeSheet();M.render(true);M.toast('تم حذف بطاقة الاختبار');},
'ac-policy-jump':el=>{document.getElementById('ac-policy-'+el.dataset.value)?.scrollIntoView({behavior:'smooth',block:'start'});},
'cp-tab':el=>{U.acCouponTab=el.dataset.value;M.render(true);},
'cp-claim':el=>{ensure();const c=S().couponWallet.find(c=>c.id===el.dataset.id);if(c?.code==='FREE100'){M.toast(freeDeliveryText);return;}if(!c||couponStatus(c)!=='claim')return;c.claimed=true;persist();U.acCouponTab='ready';M.render(true);M.toast('استلمتِ القسيمة. يمكنك استخدامها عند بلوغ الحد الأدنى.');},
'cp-apply':el=>{ensure();const c=S().couponWallet.find(c=>c.id===el.dataset.id);if(c?.code==='FREE100'){M.toast(freeDeliveryText);return;}if(!c)return;const selected=S().cart.filter(line=>line.selected!==false),subtotal=selected.reduce((sum,line)=>sum+M.product(line.id).price*line.qty,0),check=validateCoupon(c.code,subtotal);if(S().cart.length&&!selected.length){M.sheet('حددي القطع أولاً',`<p>قسيمتك محفوظة، لكن لم يتم تحديد أي قطعة للدفع. حددي القطع في حقيبة التسوق ثم طبّقي القسيمة؛ القطع غير المحددة لا تدخل في الحد الأدنى.</p><div class="button-stack">${goto('اختيار القطع في الحقيبة','cart')}${btn('العودة للقسائم','close-sheet','secondary')}</div>`);return;}if(!S().cart.length){M.sheet('ابدئي باختياراتك',`<p>قسيمتك محفوظة. أضيفي منتجات للسلة بقيمة ${amountText(rules[c.code]?.min||0)} أو أكثر، ثم طبّقي الرمز <b dir="ltr">${esc(c.code)}</b>.</p><div class="button-stack">${goto('استكشفي المنتجات','categories')}${btn('العودة للقسائم','close-sheet','secondary')}</div>`);return;}if(!check.ok){M.sheet('لم تكتمل شروط القسيمة',`<p>${esc(check.reason)}</p><p>قيمة القطع المحددة في حقيبتك: ${money(subtotal)}</p><div class="button-stack">${goto('مواصلة التسوق','categories')}${goto('عرض السلة','cart','secondary')}</div>`);return;}c.claimed=true;S().coupon=c.code;persist();M.go('cart');M.toast('تم تطبيق '+c.code+' على السلة');},
'nt-filter':el=>{U.acNotificationTab=el.dataset.value;M.render(true);},
'nt-readall':()=>{ensure();S().notificationRecords.forEach(n=>n.read=true);persist();M.render(true);M.toast('تم تحديد كل الإشعارات كمقروءة');},
'nt-open':el=>{ensure();const n=S().notificationRecords.find(n=>n.id===el.dataset.id);if(!n)return;n.read=true;persist();M.go(n.route||'account');},
'help-faq-category':el=>{U.acFAQCategory=el.dataset.value;U.acFAQOpen='';M.render();},
'help-clear-search':()=>{U.acFAQQuery='';U.acFAQCategory='all';M.render();},
'help-topic':el=>{U.acFAQCategory=el.dataset.value;U.acFAQQuery='';U.acFAQOpen='';M.go('faq');},
'help-open-faq':el=>{U.acFAQCategory='all';U.acFAQQuery='';U.acFAQOpen=el.dataset.id;M.go('faq');},
'help-ticket-filter':el=>{U.acTicketTab=el.dataset.value;M.render(true);},
'help-resolve':el=>{M.sheet('إنهاء المحادثة',`<p>هل تم حل المشكلة؟ يمكنك إعادة فتح المحادثة لاحقاً من طلبات المساعدة.</p><div class="button-stack">${btn('نعم، تم حل المشكلة','help-resolve-confirm','primary',`data-id="${esc(el.dataset.id)}"`)}${btn('متابعة المحادثة','close-sheet','secondary')}</div>`);},
'help-resolve-confirm':el=>{ensure();const t=S().tickets.find(t=>t.id===el.dataset.id);if(t){t.status='resolved';t.updated=Date.now();t.messages.push({mine:false,text:'تم إغلاق المحادثة بناءً على اختيارك. يمكنك إعادة فتحها من زر المتابعة في أي وقت داخل هذه التجربة.',time:Date.now()});persist();}M.closeSheet();M.render(true);},
'help-reopen':el=>{ensure();const t=S().tickets.find(t=>t.id===el.dataset.id);if(t){t.status='open';t.updated=Date.now();persist();M.render(true);M.toast('تمت إعادة فتح المحادثة');}}
};
const forms={
'ac-profile-form':(form,d)=>{ensure();const name=String(d.name||'').trim(),email=String(d.email||'').trim();if(name.length<2||name.length>60){inlineError('ac-profile-error','يرجى إدخال اسم من حرفين إلى ٦٠ حرفاً.');return;}if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){inlineError('ac-profile-error','يرجى إدخال بريد إلكتروني صحيح أو ترك الحقل فارغاً.');return;}if(d.birthday&&(!/^\d{4}-\d{2}-\d{2}$/.test(d.birthday)||new Date(d.birthday)>new Date()||new Date(d.birthday)<new Date('1900-01-01'))){inlineError('ac-profile-error','يرجى اختيار تاريخ ميلاد صحيح.');return;}if(!S().user){M.go('login');return;}S().user.name=name;S().profile={...S().profile,email,birthday:d.birthday||'',style:['women','men','all'].includes(d.style)?d.style:''};persist();M.toast('تم حفظ الملف الشخصي');M.go('account');},
'ac-login-phone-form':(form,d)=>{if(!d.consent){inlineError('ac-login-error','يرجى الموافقة على شروط التجربة للمتابعة.');return;}startLogin(d.phone);},
'ac-login-otp-form':(form,d)=>{ensure();const l=loginState();if(l.lockUntil>Date.now()){inlineError('ac-login-error','يرجى الانتظار دقيقة قبل المحاولة مرة أخرى.');return;}if(Date.now()>l.expires){inlineError('ac-login-error','انتهت صلاحية الرمز. أعيدي تجهيز رمز جديد.');return;}if(digits(d.otp)!=='1234'){l.attempts++;if(l.attempts>=5){l.lockUntil=Date.now()+60000;M.render(true);}else inlineError('ac-login-error','الرمز غير صحيح. رمز التجربة 1234. تبقى '+ar(5-l.attempts)+' محاولات.');return;}S().user={name:S().user?.name||'عميلة Monarca',phone:l.phone};S().security.loginRecords.unshift({time:Date.now(),phone:l.phone});S().security.loginRecords=S().security.loginRecords.slice(0,10);persist();l.step='phone';l.phone='';U.acChangingPhone=false;M.toast('تم تسجيل الدخول التجريبي');M.go('account');},
'ac-coupon-code-form':(form,d)=>{ensure();const code=String(d.code||'').trim().toUpperCase(),c=S().couponWallet.find(c=>c.code===code);if(code==='FREE100'){M.toast(freeDeliveryText);return;}if(!c||!rules[code]){M.toast('القسيمة غير متاحة. جرّبي M10.');return;}if(couponStatus(c)==='expired'||couponStatus(c)==='used'){M.toast(couponStatus(c)==='used'?'تم استخدام هذه القسيمة سابقاً.':'انتهت صلاحية القسيمة.');return;}c.claimed=true;persist();U.acCouponTab='ready';M.render(true);M.toast('تمت إضافة القسيمة إلى محفظتك');},
'ac-faq-search-form':(form,d)=>{U.acFAQQuery=String(d.query||'').trim().slice(0,100);U.acFAQCategory='all';U.acFAQOpen='';if(U.route==='faq')M.render();else M.go('faq');},
'ac-ticket-new-form':(form,d)=>{ensure();const subject=String(d.subject||'').trim(),text=String(d.message||'').trim();if(subject.length<4||subject.length>90||text.length<10||text.length>1200){inlineError('ac-ticket-error','أضيفي عنواناً من ٤–٩٠ حرفاً وتفاصيل من ١٠–١٢٠٠ حرف.');return;}const order=S().orders.find(o=>o.id===d.order);const now=Date.now(),id='CARE-'+now.toString().slice(-8),type=['order','payment','return','product','account','other'].includes(d.type)?d.type:'other';S().tickets.unshift({id,type,subject,orderId:order?.id||'',status:'open',created:now,updated:now,messages:[{mine:false,text:'أهلاً بكِ في عناية Monarca التجريبية. كل ما تكتبينه يبقى في هذا المتصفح، والردود آلية لعرض التجربة.',time:now},{mine:true,text,time:now}]});U.acSupportOrder='';U.acSupportType='';persist();replyLater(id,text);M.go('ticket/'+id);},
'ac-ticket-reply-form':(form,d)=>{ensure();const id=form.dataset.id,t=S().tickets.find(t=>t.id===id),text=String(d.message||'').trim();if(!t||t.status==='resolved'||U.acReplyPending===id)return;if(!text||text.length>1200){M.toast('أضيفي رسالة من حرف واحد إلى ١٢٠٠ حرف.');return;}t.messages.push({mine:true,text,time:Date.now()});t.updated=Date.now();persist();replyLater(id,text);M.render(true);},
'ac-card-add-form':(form,d)=>{ensure();if(!['visa','mastercard'].includes(d.network))return;const network=d.network,last4=network==='visa'?'4242':'4444',existing=S().paymentTokens.find(t=>t.network===network&&t.last4===last4),makeDefault=!!d.default||!S().paymentTokens.length;if(makeDefault)S().paymentTokens.forEach(t=>t.default=false);if(existing){existing.holder=String(d.holder||'MONARCA DEMO').trim().slice(0,60)||'MONARCA DEMO';existing.default=makeDefault||existing.default;}else S().paymentTokens.push({id:'demo-'+network,network,last4,holder:String(d.holder||'MONARCA DEMO').trim().slice(0,60)||'MONARCA DEMO',isDemo:true,default:makeDefault});persist();M.closeSheet();M.render(true);M.toast(existing?'تم تحديث بطاقة الاختبار':'تمت إضافة بطاقة الاختبار');}
};
M.register({routes:{account,profile,login,coupons,notifications,support,ticket,tickets,faq,settings,policy,'payment-methods':paymentMethods,about,security,preferences:preferencesView,region},actions,forms,onRoute:(name)=>{ensure();if(name==='faq'&&U.acFAQOpen)setTimeout(()=>document.getElementById('ac-faq-'+U.acFAQOpen)?.scrollIntoView({behavior:'smooth',block:'center'}),50);}});
})();




